func (t *TransmuterModule) enrichMultiShadowBatchRows(
	ctx context.Context,
	shadowDB *gorm.DB,
	row *masterBindingRuntime,
	rows []shadowBatchRow,
) []shadowBatchRow {
	if row == nil || len(rows) == 0 || shadowDB == nil {
		return rows
	}
	sources, _ := transmute.ParseShadowSources(row.TransformSpec)
	if len(sources) == 0 {
		return rows
	}
	sourceIDs := make([]string, 0, len(rows))
	for _, r := range rows {
		if r.SourceID != "" && !r.Deleted {
			sourceIDs = append(sourceIDs, r.SourceID)
		}
	}
	if len(sourceIDs) == 0 {
		return rows
	}

	secondaryMap := t.fetchMergedShadowRawMap(ctx, shadowDB, row, sources, sourceIDs, true)
	if len(secondaryMap) == 0 {
		return rows
	}
	for i := range rows {
		if secRaw, ok := secondaryMap[rows[i].SourceID]; ok && len(secRaw) > 0 {
			rows[i].RawData = mergeShadowRawJSON(rows[i].RawData, secRaw)
		}
	}
	return rows
}

func (t *TransmuterModule) enrichMultiShadowEvents(
	ctx context.Context,
	row *masterBindingRuntime,
	events []shadowmodel.TransmuteEventItem,
) []shadowmodel.TransmuteEventItem {
	if row == nil || len(events) == 0 || t.connMgr == nil {
		return events
	}
	sources, _ := transmute.ParseShadowSources(row.TransformSpec)
	if len(sources) == 0 {
		return events
	}
	shadowDB, err := t.connMgr.GetShadowDB(ctx, row.ShadowConnectionKey)
	if err != nil || shadowDB == nil {
		return events
	}
	sourceIDs := make([]string, 0, len(events))
	for _, ev := range events {
		if !ev.IsDelete && ev.Op != "d" && ev.SourceID != "" {
			sourceIDs = append(sourceIDs, ev.SourceID)
		}
	}
	if len(sourceIDs) == 0 {
		return events
	}
	// Khi event phát sinh từ Secondary Shadow (vd: transaction_history_payload),
	// cần lấy cả Primary Shadow + các Secondary Shadow để ghép đủ _raw_data.
	mergedByID := t.fetchMergedShadowRawMap(ctx, shadowDB, row, sources, sourceIDs, false)
	if len(mergedByID) == 0 {
		return events
	}
	out := make([]shadowmodel.TransmuteEventItem, len(events))
	copy(out, events)
	for i := range out {
		if out[i].IsDelete || out[i].Op == "d" {
			continue
		}
		if dbMerged, ok := mergedByID[out[i].SourceID]; ok && len(dbMerged) > 0 {
			if len(out[i].RawData) > 0 {
				out[i].RawData = string(mergeShadowRawJSON(dbMerged, []byte(out[i].RawData)))
			} else {
				out[i].RawData = string(dbMerged)
			}
		}
	}

