		return
	}

	for path, meta := range typeMap {
		parts := strings.Split(strings.TrimSpace(path), ".")
		if len(parts) == 0 || parts[0] == "" {
			continue
		}
		applyBSONTypeAtPath(doc, parts, meta)
	}

	if _, hasV := doc["__v"]; !hasV {
		doc["__v"] = int32(0)
	}

